, Property 7: Avatar URL Validation","tree":{"sha":"d553738f8aba60d56bc1864ed2a871e6a7b9fe65","url":"https://api.github.com/repos/sanitaravel/Real-Time-Chat/git/trees/d553738f8aba60d56bc1864ed2a871e6a7b9fe65"},"url":"https://api.github.com/repos/sanitaravel/Real-Time-Chat/git/commits/5a6f5435552eaaacdb18c11ac2f3a5286512a3fc","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/58359823?v=4","events_url":"https://api.github.com/users/sanitaravel/events{/privacy}","followers_url":"https://api.github.com/users/sanitaravel/followers","following_url":"https://api.github.com/users/sanitaravel/following{/other_user}","gists_url":"https://api.github.com/users/sanitaravel/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sanitaravel","id":58359823,"login":"sanitaravel","node_id":"MDQ6VXNlcjU4MzU5ODIz","organizations_url":"https://api.github.com/users/sanitaravel/orgs","received_events_url":"https://api.github.com/users/sanitaravel/received_events","repos_url":"https://api.github.com/users/sanitaravel/repos","site_admin":false,"starred_url":"https://api.github.com/users/sanitaravel/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sanitaravel/subscriptions","type":"User","url":"https://api.github.com/users/sanitaravel","user_view_type":"public"},"html_url":"https://github.com/sanitaravel/Real-Time-Chat/commit/5a6f5435552eaaacdb18c11ac2f3a5286512a3fc","node_id":"C_kwDOSwVg6doAKDVhNmY1NDM1NTUyZWFhYWNkYjE4YzExYWMyZjNhNTI4NjUxMmEzZmM","parents":[{"html_url":"https://github.com/sanitaravel/Real-Time-Chat/commit/8050a8489a3a0b65568480eebb043749272642a4","sha":"8050a8489a3a0b65568480eebb043749272642a4","url":"https://api.github.com/repos/sanitaravel/Real-Time-Chat/commits/8050a8489a3a0b65568480eebb043749272642a4"}],"sha":"5a6f5435552eaaacdb18c11ac2f3a5286512a3fc","url":"https://api.github.com/repos/sanitaravel/Real-Time-Chat/c