plied. FileModule added for local filesystem avatar storage with cleanup on failure. Fixes graphql-upload v17 ESM import incompatibility by defining a local FileUpload interface and using require() subpath import for GraphQLUpload scalar.","tree":{"sha":"ccdfeb75aa8834b42f8e1ffa950303c333223f5b","url":"https://api.github.com/repos/sanitaravel/Real-Time-Chat/git/trees/ccdfeb75aa8834b42f8e1ffa950303c333223f5b"},"url":"https://api.github.com/repos/sanitaravel/Real-Time-Chat/git/commits/71caf5cd1a5d4fa0ae8b62d52966585bc99c0d46","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/58359823?v=4","events_url":"https://api.github.com/users/sanitaravel/events{/privacy}","followers_url":"https://api.github.com/users/sanitaravel/followers","following_url":"https://api.github.com/users/sanitaravel/following{/other_user}","gists_url":"https://api.github.com/users/sanitaravel/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/sanitaravel","id":58359823,"login":"sanitaravel","node_id":"MDQ6VXNlcjU4MzU5ODIz","organizations_url":"https://api.github.com/users/sanitaravel/orgs","received_events_url":"https://api.github.com/users/sanitaravel/received_events","repos_url":"https://api.github.com/users/sanitaravel/repos","site_admin":false,"starred_url":"https://api.github.com/users/sanitaravel/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/sanitaravel/subscriptions","type":"User","url":"https://api.github.com/users/sanitaravel","user_view_type":"public"},"html_url":"https://github.com/sanitaravel/Real-Time-Chat/commit/71caf5cd1a5d4fa0ae8b62d52966585bc99c0d46","node_id":"C_kwDOSwVg6doAKDcxY2FmNWNkMWE1ZDRmYTBhZThiNjJkNTI5NjY1ODViYzk5YzBkNDY","parents":[{"html_url":"https://github.com/sanitaravel/Real-Time-Chat/commit/668ece39640ed19d3362077100abab36d3f5ac4a","sha":"668ece39640ed19d3362077100abab36d3f5ac4a","url":"https://api.github